+export async function listResources() {
+  return {
+    resourceTemplates: [
+      {
+        uriTemplate: URI_TEMPLATE,
+        name: 'User Profile',
+        description: 'A user profile, addressable by user id.',
+        mimeType: MIME_TYPE,
+      },
+    ],
+  };
+}
+
+export async function readResource(uri) {
+  if (typeof uri !== 'string' || uri.trim() === '') {
+    throw invalidParams('uri is required');
+  }
+  const match = PROFILE_PATTERN.exec(uri);
+  if (!match) {
+    throw invalidParams(`Unknown resource URI: ${uri}`);
+  }
+  const userId = match[1];
+  if (!Object.prototype.hasOwnProperty.call(PROFILES, userId)) {
+    throw invalidParams(`Unknown user: ${userId}`);
+  }
+  return {
+    contents: [
+      {
+        uri,
+        mimeType: MIME_TYPE,
+        text: PROFILES[userId],
+      },
+    ],
+  };
+}
